const { chromium } = require('playwright');
const http = require('http');
const fs = require('fs');
const path = require('path');

const PORT = 8765;
const POSTER_URL = `http://localhost:${PORT}/poster.html`;
const OUTPUT_PATH = '/app/output/final_poster.png';

const mimeTypes = {
  '.html': 'text/html',
  '.js': 'application/javascript',
  '.css': 'text/css',
  '.png': 'image/png',
  '.svg': 'image/svg+xml',
  '.woff2': 'font/woff2',
  '.woff': 'font/woff',
  '.ttf': 'font/ttf',
};

const server = http.createServer((req, res) => {
  const urlPath = req.url === '/' ? '/poster.html' : req.url;
  const safePath = path.normalize(urlPath).replace(/^(\.\.[\/\\])+/, '');
  const filePath = path.join('/app', safePath);

  fs.readFile(filePath, (err, data) => {
    if (err) {
      res.writeHead(404);
      res.end('Not Found');
      return;
    }
    const ext = path.extname(filePath).toLowerCase();
    const mime = mimeTypes[ext] || 'application/octet-stream';
    res.writeHead(200, {
      'Content-Type': mime,
      'Access-Control-Allow-Origin': '*',
    });
    res.end(data);
  });
});

async function render() {
  return new Promise((resolve, reject) => {
    server.listen(PORT, async () => {
      console.log(`Server listening on ${PORT}`);
      try {
        const browser = await chromium.launch({ headless: true });
        const context = await browser.newContext({
          viewport: { width: 1080, height: 1920 },
          deviceScaleFactor: 2,
        });
        const page = await context.newPage();

        await page.goto(POSTER_URL, { waitUntil: 'networkidle' });

        // Wait for fonts and infographic render
        await page.waitForFunction(() => {
          return document.fonts.status === 'loaded' || document.readyState === 'complete';
        }, { timeout: 15000 });

        // Extra wait for SVG/Canvas rendering
        await page.waitForTimeout(3000);

        // Screenshot the #poster div exactly
        const poster = await page.$('#poster');
        await poster.screenshot({
          path: OUTPUT_PATH,
          type: 'png',
        });

        console.log(`Saved poster to ${OUTPUT_PATH}`);
        await browser.close();
        resolve();
      } catch (e) {
        reject(e);
      } finally {
        server.close();
      }
    });
  });
}

render().catch(err => {
  console.error(err);
  process.exit(1);
});

